const fs = require('fs');
const path = require('path');

const logPath = 'C:\\Users\\Dan\\.gemini\\antigravity-ide\\brain\\6a740ec8-828b-40a3-83b9-6d3c3bd74b65\\.system_generated\\logs\\transcript_full.jsonl';

// Read log file
const logContent = fs.readFileSync(logPath, 'utf-8');

// Collect all OCR page blocks
const ocrPages = [];
const pageRegex = /==Start of OCR for page (\d+)==([\s\S]*?)==End of OCR for page \1==/g;
let match;
while ((match = pageRegex.exec(logContent)) !== null) {
  const pageNum = parseInt(match[1], 10);
  const text = match[2];
  ocrPages.push({ pageNum, text });
}

ocrPages.sort((a, b) => a.pageNum - b.pageNum);

console.log(`Extracted ${ocrPages.length} OCR pages from transcript log.`);

// Combine text from page 21 to page 181 (where sections 1-320 live)
const constitutionPages = ocrPages.filter(p => p.pageNum >= 21 && p.pageNum <= 181);

let combinedText = '';
for (const p of constitutionPages) {
  // Clean header/footer artifacts
  let clean = p.text
    .replace(/Back To Top/gi, '')
    .replace(/Nigerian Constitution/gi, '')
    .replace(/^\s*\d+\s*$/gm, ''); // page numbers on own lines
  combinedText += clean + '\n';
}

console.log(`Combined text length: ${combinedText.length} characters.`);
fs.writeFileSync(path.join(__dirname, 'raw_ocr_combined.txt'), combinedText, 'utf-8');

const fs = require('fs');
const readline = require('readline');
const path = require('path');

const logPath = 'C:\\Users\\Dan\\.gemini\\antigravity-ide\\brain\\6a740ec8-828b-40a3-83b9-6d3c3bd74b65\\.system_generated\\logs\\transcript_full.jsonl';

const fileStream = fs.createReadStream(logPath);
const rl = readline.createInterface({
  input: fileStream,
  crlfDelay: Infinity
});

let foundText = '';

rl.on('line', (line) => {
  if (line.includes('==Start of OCR for page')) {
    try {
      const parsed = JSON.parse(line);
      const content = JSON.stringify(parsed);
      foundText += content + '\n';
    } catch (e) {
      foundText += line + '\n';
    }
  }
});

rl.on('close', () => {
  console.log(`Found lines with OCR. Length: ${foundText.length}`);
  fs.writeFileSync(path.join(__dirname, 'found_lines.txt'), foundText, 'utf-8');
});

const fs = require('fs');
const path = require('path');

const raw = fs.readFileSync(path.join(__dirname, 'found_lines.txt'), 'utf-8');
const lines = raw.split('\n').filter(Boolean);

let fullText = '';
for (const l of lines) {
  try {
    const obj = JSON.parse(l);
    if (obj.content) {
      fullText += obj.content + '\n';
    }
  } catch (e) {
    fullText += l + '\n';
  }
}

console.log(`Parsed text length: ${fullText.length}`);

// Find all OCR pages (from page 21 to page 181)
const pages = [];
const pageRegex = /==Start of OCR for page (\d+)==([\s\S]*?)==End of OCR for page \1==/g;
let m;
while ((m = pageRegex.exec(fullText)) !== null) {
  const pNum = parseInt(m[1], 10);
  pages.push({ pageNum: pNum, text: m[2] });
}

pages.sort((a, b) => a.pageNum - b.pageNum);
console.log(`Found ${pages.length} OCR page blocks!`);

if (pages.length > 0) {
  const constitutionPages = pages.filter(p => p.pageNum >= 21 && p.pageNum <= 181);
  console.log(`Constitution text pages count (21 to 181): ${constitutionPages.length}`);

  let combined = '';
  for (const cp of constitutionPages) {
    let clean = cp.text
      .replace(/Back To Top/gi, '')
      .replace(/Nigerian Constitution/gi, '')
      .replace(/^\s*\d+\s*$/gm, '');
    combined += clean + '\n';
  }

  fs.writeFileSync(path.join(__dirname, 'raw_constitution_clean.txt'), combined, 'utf-8');
}

const fs = require('fs');
