const fs = require('fs');
const readline = require('readline');

const logPath = 'C:\\Users\\Dan\\.gemini\\antigravity-ide\\brain\\6a740ec8-828b-40a3-83b9-6d3c3bd74b65\\.system_generated\\logs\\transcript_full.jsonl';

